export fn largest_square_area_in_matrix(v:[*]const i64,n:usize)i64{if(n<2 or n>66)return -2;const r=v[0];const c=v[1];if(r<1 or r>8 or c<1 or c>8 or n!=2+@as(usize,@intCast(r*c)))return -2;var d:[9][9]i64=@splat(@splat(0));for(0..@as(usize,@intCast(r*c)))|i|{if(v[2+i]!=0 and v[2+i]!=1)return -2;}var best:i64=0;var i:usize=@intCast(r);while(i>0){i-=1;var j:usize=@intCast(c);while(j>0){j-=1;if(v[2+i*@as(usize,@intCast(c))+j]==1){d[i][j]=1+@min(d[i+1][j],@min(d[i][j+1],d[i+1][j+1]));best=@max(best,d[i][j]);}}}return best;}
